using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using UnityEngine.Animations;using UnityEngine.Playables;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){var rows=new List<string>();string hero="Assets/Player/Hero/Heraklios.fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(hero);var avatar=AssetDatabase.LoadAllAssetsAtPath(hero).OfType<Avatar>().Single(a=>a.isHuman);if(!avatar.isValid||importer.animationType!=ModelImporterAnimationType.Human||importer.avatarSetup!=ModelImporterAvatarSetup.CreateFromThisModel)throw new Exception("Invalid hero rig");rows.Add("hero="+hero+"|valid="+avatar.isValid+"|human="+avatar.isHuman+"|rig="+importer.animationType+"|avatarDefinition="+importer.avatarSetup);int files=0;foreach(var pack in Directory.GetDirectories("Assets/Player/Hero/Animations")){var paths=Directory.GetFiles(pack,"*.fbx");int valid=0;foreach(var path in paths){var clips=AssetDatabase.LoadAllAssetsAtPath(path.Replace('\\','/')).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToArray();if(clips.Length==0||clips.Any(c=>!c.isHumanMotion))throw new Exception("Nonhuman clip "+path);valid++;}files+=valid;string sample=paths.OrderBy(p=>p).First().Replace('\\','/');var clip=AssetDatabase.LoadAllAssetsAtPath(sample).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview__"));var preview=EditorSceneManager.NewPreviewScene();var clone=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(hero));UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(clone,preview);var anim=clone.GetComponent<Animator>();anim.avatar=avatar;anim.runtimeAnimatorController=null;anim.applyRootMotion=false;anim.cullingMode=AnimatorCullingMode.AlwaysAnimate;var graph=PlayableGraph.Create("HerakliosRetargetTest");try{var output=AnimationPlayableOutput.Create(graph,"sample",anim);var playable=AnimationClipPlayable.Create(graph,clip);output.SetSourcePlayable(playable);graph.Play();graph.Evaluate(Mathf.Min(.3f,clip.length*.3f));for(int i=0;i<(int)HumanBodyBones.LastBone;i++){var bone=anim.GetBoneTransform((HumanBodyBones)i);if(bone&&(float.IsNaN(bone.position.x)||float.IsInfinity(bone.position.y)))throw new Exception("Nonfinite retarget "+sample);}rows.Add(Path.GetFileName(pack)+"|humanoid="+valid+"|sample="+sample+"|retarget=PASS|hips="+anim.GetBoneTransform(HumanBodyBones.Hips).position.ToString("R"));}finally{graph.Destroy();UnityEngine.Object.DestroyImmediate(clone);EditorSceneManager.ClosePreviewScene(preview);}}
var ac=AssetDatabase.LoadAssetAtPath<AnimatorController>("Assets/Player/Hero/MMHero.controller");foreach(var st in ac.layers[0].stateMachine.states){var blend=st.state.motion as BlendTree;if(blend){rows.Add("state="+st.state.name+"|blend="+blend.blendParameter+"|"+string.Join(";",blend.children.Select(c=>c.threshold+":"+AssetDatabase.GetAssetPath(c.motion))));}else rows.Add("state="+st.state.name+"|clip="+AssetDatabase.GetAssetPath(st.state.motion));}rows.Add("animation_fbx_count="+files);File.WriteAllLines("Validation/Hero/rig_animation_validation.txt",rows);result.Log("HERAKLIOS avatar valid/human; "+files+" humanoid animation FBXs; 8 pack retarget samples PASS");}}
